import pytest
from hypothesis import given, HealthCheck
import hypothesis.strategies as st
from solution import iscube


def _ref_iscube(a):
    """Obviously correct integer-arithmetic reference model."""
    if a == 0:
        return True
    x = -a if a < 0 else a
    # upper bound: 2**k with 3*k >= bit_length(x)
    k = (x.bit_length() + 2) // 3
    hi = (1 << (k + 1)) + 1
    lo = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        c = mid * mid * mid
        if c == x:
            return True
        if c < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return False


# ---- explicit spec examples ----
@pytest.mark.parametrize(
    "a, expected",
    [
        (1, True),
        (2, False),
        (-1, True),
        (64, True),
        (0, True),
        (180, False),
    ],
)
def test_examples_match_spec(a, expected):
    assert iscube(a) is expected


def test_zero_is_cube():
    assert iscube(0) is True


def test_one_and_negative_one_are_cubes():
    assert iscube(1) is True
    assert iscube(-1) is True


def test_small_perfect_cubes_are_true():
    for a in [8, -8, 27, -27, 64, -64, 125, -125, 216, -216, 1000, -1000]:
        assert iscube(a) is True, f"iscube({a}) should be True"


def test_small_non_cubes_are_false():
    for a in [2, 3, 4, 5, 6, 7, 9, 10, 26, 28, 63, 65, 180, -2, -9, -180]:
        assert iscube(a) is False, f"iscube({a}) should be False"


def test_large_perfect_cube_exact():
    # 10**10 cubed = 10**30, well beyond float exact integers
    n = 10**10
    assert iscube(n**3) is True
    assert iscube(-(n**3)) is True


def test_very_large_perfect_cube_exact():
    n = 10**100
    assert iscube(n**3) is True
    assert iscube(-(n**3)) is True


def test_huge_input_does_not_crash_and_is_true():
    # float(abs(a)) overflows to inf here; must still return True, not raise
    n = 10**200
    a = n**3
    assert iscube(a) is True
    assert iscube(-a) is True


def test_huge_non_cube_does_not_crash_and_is_false():
    n = 10**200
    a = n**3 + 1
    assert _ref_iscube(a) is False  # sanity on reference
    assert iscube(a) is False
    assert iscube(-a) is False


@given(n=st.integers(min_value=-1000, max_value=1000))
def test_cube_roundtrip_small(n):
    assert iscube(n**3) is True
    assert iscube(-(n**3)) is True


@given(n=st.integers(min_value=-(10**12), max_value=10**12))
def test_cube_roundtrip_large(n):
    # Every integer cubed must be recognised, however large.
    a = n**3
    assert iscube(a) is True
    assert iscube(-a) is True


@given(a=st.integers(min_value=-(10**18), max_value=10**18))
def test_equivalence_to_integer_reference(a):
    assert iscube(a) is _ref_iscube(a)


@given(a=st.integers(min_value=-(10**36), max_value=10**36))
def test_equivalence_to_integer_reference_huge(a):
    assert iscube(a) is _ref_iscube(a)


@given(a=st.integers(min_value=-(10**6), max_value=10**6))
def test_sign_symmetry(a):
    # a = k^3  <=>  -a = (-k)^3
    assert iscube(a) is iscube(-a)


@given(n=st.integers(min_value=2, max_value=10**12))
def test_between_consecutive_cubes_is_not_cube(n):
    # n^3 < n^3+1 < (n+1)^3, so n^3+1 is never a cube for n>=1
    a = n**3 + 1
    assert _ref_iscube(a) is False  # reference sanity
    assert iscube(a) is False
    assert iscube(-a) is False


@given(n=st.integers(min_value=2, max_value=10**12))
def test_just_below_cube_is_not_cube(n):
    # (n-1)^3 < n^3-1 < n^3 for n>=2
    a = n**3 - 1
    assert _ref_iscube(a) is False
    assert iscube(a) is False
    assert iscube(-a) is False


@given(a=st.integers(min_value=-(10**6), max_value=10**6))
def test_returns_bool_type(a):
    r = iscube(a)
    assert r is True or r is False
